-- 0024 (part 2 of 3): the old weapons become the tin ones (docs/design.md §14). GENERATED by scripts/tin-sql.ts.
-- Run after 0023.
--
-- ⚠ CHANGES PLAYER DATA (on purpose, nobody loses anything): Brass Knuckles → Tin Knuckles, Baseball Bat → Tin Bat,
-- Knife → Tin Knife, in every bag, in what people wield, in graves and on the ground. The thugs drop the tin knife; Ray
-- sells the three tin weapons (knuckles $50, bat $100, knife $150); the old items are removed.
-- It all runs in one transaction: if anything goes wrong, nothing is changed.
-- DRY RUN: change the last line "commit;" to "rollback;", run it, look at the result, then run it again with "commit;".

begin;

-- In bags and graves: the old item's count moves to the tin one.
update public.players set inventory = (inventory - 'brass_knuckles') || jsonb_build_object('tin_knuckles', coalesce((inventory ->> 'tin_knuckles')::int, 0) + (inventory ->> 'brass_knuckles')::int) where inventory ? 'brass_knuckles';
update public.players set inventory = (inventory - 'baseball_bat') || jsonb_build_object('tin_bat', coalesce((inventory ->> 'tin_bat')::int, 0) + (inventory ->> 'baseball_bat')::int) where inventory ? 'baseball_bat';
update public.players set inventory = (inventory - 'knife') || jsonb_build_object('tin_knife', coalesce((inventory ->> 'tin_knife')::int, 0) + (inventory ->> 'knife')::int) where inventory ? 'knife';
update public.graves set items = (items - 'brass_knuckles') || jsonb_build_object('tin_knuckles', coalesce((items ->> 'tin_knuckles')::int, 0) + (items ->> 'brass_knuckles')::int) where items ? 'brass_knuckles';
update public.graves set items = (items - 'baseball_bat') || jsonb_build_object('tin_bat', coalesce((items ->> 'tin_bat')::int, 0) + (items ->> 'baseball_bat')::int) where items ? 'baseball_bat';
update public.graves set items = (items - 'knife') || jsonb_build_object('tin_knife', coalesce((items ->> 'tin_knife')::int, 0) + (items ->> 'knife')::int) where items ? 'knife';
-- What people wield.
update public.players set equipment = jsonb_set(equipment, '{weapon}', to_jsonb(case equipment ->> 'weapon' when 'brass_knuckles' then 'tin_knuckles' when 'baseball_bat' then 'tin_bat' when 'knife' then 'tin_knife' end))
where equipment ->> 'weapon' in ('brass_knuckles', 'baseball_bat', 'knife');
-- On the ground, in the thugs' loot, in Ray's shop.
update public.ground_items set item = case item when 'brass_knuckles' then 'tin_knuckles' when 'baseball_bat' then 'tin_bat' when 'knife' then 'tin_knife' end where item in ('brass_knuckles', 'baseball_bat', 'knife');
update public.loot set item = case item when 'brass_knuckles' then 'tin_knuckles' when 'baseball_bat' then 'tin_bat' when 'knife' then 'tin_knife' end where item in ('brass_knuckles', 'baseball_bat', 'knife');
delete from public.shop_items where shop = 'weapons';
insert into public.shop_items (shop, item, price) values
  ('weapons', 'tin_knuckles', 50),
  ('weapons', 'tin_bat', 100),
  ('weapons', 'tin_knife', 150);
-- The old items.
delete from public.items where id in ('brass_knuckles', 'baseball_bat', 'knife');

-- Check: nothing old is left anywhere (stops and undoes everything if something is).
do $do$
begin
  if exists (select 1 from public.players where inventory ?| array['brass_knuckles', 'baseball_bat', 'knife'] or equipment ->> 'weapon' in ('brass_knuckles', 'baseball_bat', 'knife'))
     or exists (select 1 from public.graves where items ?| array['brass_knuckles', 'baseball_bat', 'knife'])
     or exists (select 1 from public.ground_items where item in ('brass_knuckles', 'baseball_bat', 'knife'))
     or exists (select 1 from public.loot where item in ('brass_knuckles', 'baseball_bat', 'knife')) then
    raise exception 'old weapons are still somewhere: nothing was changed';
  end if;
end $do$;
select (select count(*) from public.players where equipment ->> 'weapon' like 'tin_%') as wielding_tin,
  (select string_agg(item || ' $' || price, ', ') from public.shop_items where shop = 'weapons') as rays_shop;

commit;
